import java.util.Scanner;

public class Main {
    static boolean isInside(int x, int y, int cx, int cy, int r) {
        return Math.pow(x - cx, 2) + Math.pow(y - cy, 2) < (long) r * r;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();

        while (T-- > 0) {
            int x1 = sc.nextInt(), y1 = sc.nextInt();
            int x2 = sc.nextInt(), y2 = sc.nextInt();
            int n = sc.nextInt();
            int count = 0;

            for (int i = 0; i < n; i++) {
                int cx = sc.nextInt(), cy = sc.nextInt(), r = sc.nextInt();
                boolean inStart = isInside(x1, y1, cx, cy, r);
                boolean inEnd = isInside(x2, y2, cx, cy, r);

                if (inStart != inEnd) count++;
            }
            System.out.println(count);
        }
    }
}

#include <iostream>
using namespace std;

bool isInside(int x, int y, int cx, int cy, int r) {
    return (long long)(x - cx) * (x - cx) + (long long)(y - cy) * (y - cy) < (long long) r * r;
}

int main() {
    int T;
    cin >> T;

    while (T--) {
        int x1, y1, x2, y2, n;
        cin >> x1 >> y1 >> x2 >> y2 >> n;
        int count = 0;

        for (int i = 0; i < n; i++) {
            int cx, cy, r;
            cin >> cx >> cy >> r;
            bool inStart = isInside(x1, y1, cx, cy, r);
            bool inEnd = isInside(x2, y2, cx, cy, r);

            if (inStart != inEnd) count++;
        }
        cout << count << endl;
    }
    return 0;
}
